const payload = $input.all();


let code = null;
for (const item of payload) {
  if (item.json && item.json.payload && Array.isArray(item.json.payload)) {
    for (const payloadItem of item.json.payload) {
      if (payloadItem && payloadItem.title === "Код для входа в приложение") {
        const match = payloadItem.text.match(/\d{6}/);
        if (match) {
          code = match[0]
          break;
        }
      }
    }
    if (code) {
      break;
    }
  }
}

return [{ json: { code }}];

